package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeBindings;
import java.io.*;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;

/**
 * Unit tests for SimpleType._narrow method.
 * Since _narrow is protected, we use reflection to access it.
 */
public class SimpleType__narrow_TriageGen0Test {

    @SuppressWarnings("unchecked")
    private <T> T invokeNarrow(SimpleType type, Class<?> subclass) throws Exception {
        Method method = SimpleType.class.getDeclaredMethod("_narrow", Class.class);
        method.setAccessible(true);
        return (T) method.invoke(type, subclass);
    }

    @Test
    public void testNarrow_SameClassReturnsThis() throws Exception {
        // Arrange
        Class<?> clazz = String.class;
        SimpleType type = SimpleType.construct(clazz);

        // Act
        SimpleType result = invokeNarrow(type, clazz);

        // Assert
        assertSame("If subclass is the same as _class, it should return 'this'", type, result);
    }






}

package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeBindings;
import java.io.*;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;

/**
 * Unit tests for SimpleType._narrow method.
 * Since _narrow is protected, we use reflection to access it.
 */
public class SimpleType__narrow_TriageGen0Test {

    @SuppressWarnings("unchecked")
    private <T> T invokeNarrow(SimpleType type, Class<?> subclass) throws Exception {
        Method method = SimpleType.class.getDeclaredMethod("_narrow", Class.class);
        method.setAccessible(true);
        return (T) method.invoke(type, subclass);
    }



    @Test
    public void testNarrow_DifferentClassReturnsNewSimpleType() throws Exception {
        // Arrange
        SimpleType type = SimpleType.construct(String.class);
        Class<?> subclass = Integer.class;

        // Act
        JavaType result = invokeNarrow(type, subclass);

        // Assert
        assertNotSame("Should return a new instance when class is different", type, result);
        assertEquals("The new type should represent the subclass class", subclass, result.getRawClass());
    }




}

package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeBindings;
import java.io.*;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;

/**
 * Unit tests for SimpleType._narrow method.
 * Since _narrow is protected, we use reflection to access it.
 */
public class SimpleType__narrow_TriageGen0Test {

    @SuppressWarnings("unchecked")
    private <T> T invokeNarrow(SimpleType type, Class<?> subclass) throws Exception {
        Method method = SimpleType.class.getDeclaredMethod("_narrow", Class.class);
        method.setAccessible(true);
        return (T) method.invoke(type, subclass);
    }







    @Test
    public void testNarrow_WithNullSubclass() throws Exception {
        // Arrange
        SimpleType type = SimpleType.construct(String.class);

        // Act & Assert
        // Even though passing null is logically incorrect for most use cases, 
        // we test the code path: if (_class == subclass) -> false, then return new SimpleType
        try {
            JavaType result = invokeNarrow(type, null);
            assertNotSame(type, result);
            assertEquals(null, result.getRawClass());
        } catch (Exception e) {
            // Depending on how SimpleType handles null in its constructor, 
            // this might throw a NullPointerException.
        }
    }
}
